def search_clinical_trials_and_save_studies_to_csv(search_expr, max_studies=None, save_csv=None, filename=None, fields=None, **_extra):
    import json, os, datetime, time, csv, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- Validation ----
    if not isinstance(search_expr, str) or not search_expr.strip():
        return _err("VALIDATION_ERROR", "search_expr must be a non-empty string")

    if max_studies is None:
        max_studies = 10
    if not isinstance(max_studies, int):
        return _err("VALIDATION_ERROR", "max_studies must be an integer")
    if max_studies < 1 or max_studies > 1000:
        return _err("VALIDATION_ERROR", "max_studies must be between 1 and 1000")

    if save_csv is None:
        save_csv = True
    if not isinstance(save_csv, bool):
        return _err("VALIDATION_ERROR", "save_csv must be a boolean")

    if filename is None:
        filename = "corona_fields.csv"
    if save_csv:
        if not isinstance(filename, str) or not (1 <= len(filename) <= 255):
            return _err("VALIDATION_ERROR", "filename must be a string of length 1..255 when save_csv=true")
        # prevent traversal
        if ".." in filename or "/" in filename or "\\" in filename:
            return _err("VALIDATION_ERROR", "filename must not contain path traversal or directory separators")
    else:
        filename = None

    if fields is not None:
        if not isinstance(fields, list):
            return _err("VALIDATION_ERROR", "fields must be an array when provided")
        for i, f in enumerate(fields):
            if not isinstance(f, str) or not f.strip():
                return _err("VALIDATION_ERROR", f"fields[{i}] must be a non-empty string")

    # ---- Load datastore ----
    reqs = _load("ct_search_requests.json")
    studies = _load("ct_studies.json")
    search_results = _load("ct_search_results.json")
    exports = _load("csv_exports.json")

    if not isinstance(reqs, list): reqs = []
    if not isinstance(studies, list): studies = []
    if not isinstance(search_results, list): search_results = []
    if not isinstance(exports, list): exports = []

    # ---- Helpers ----
    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix, existing_rows):
        # vendor datastore uses prefix_ + something; keep stable, unique, human-readable
        # Ensure uniqueness across this file
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        seq = 1
        existing = set()
        for r in existing_rows:
            if isinstance(r, dict):
                rid = r.get("id")
                if isinstance(rid, str):
                    existing.add(rid)
        while True:
            cand = f"{prefix}_{ts}_{seq:06d}"
            if cand not in existing:
                return cand
            seq += 1

    def _tokenize(s):
        # turn "COVID-19+AND+Paxlovid&aggFilters=..." into useful tokens
        s = s.lower()
        s = s.replace("+", " ")
        s = re.sub(r"[%_]", " ", s)
        # split on non-alphanum
        parts = re.split(r"[^a-z0-9]+", s)
        return [p for p in parts if p and p not in ("and", "or", "not")]

    def _study_text(st):
        chunks = []
        for k in ("nct_id", "brief_title", "official_title", "overall_status", "study_type"):
            v = st.get(k)
            if isinstance(v, str) and v:
                chunks.append(v.lower())
        conds = st.get("conditions")
        if isinstance(conds, list):
            for c in conds:
                if isinstance(c, str) and c:
                    chunks.append(c.lower())
        return " ".join(chunks)

    # ---- Create search request row (queued -> running) ----
    req_id = _new_id("ctsrch", reqs)
    req_row = {
        "id": req_id,
        "search_type": "expression",
        "search_expr": search_expr,
        "keyword": None,
        "condition": None,
        "max_studies": max_studies,
        "requested_fields": fields if fields is not None else None,
        "save_csv": bool(save_csv),
        "filename": filename if save_csv else None,
        "results_count": None,
        "error_message": None,
        "status": "queued",
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(req_row)
    _save("ct_search_requests.json", reqs)

    # Transition queued -> running
    req_row["status"] = "running"
    req_row["updated_at"] = now
    _save("ct_search_requests.json", reqs)

    # ---- Execute "search" over cached ct_studies ----
    tokens = _tokenize(search_expr)
    matched = []
    for st in studies:
        if not isinstance(st, dict):
            continue
        # enforce basic nct_id format when present
        nct = st.get("nct_id")
        if not isinstance(nct, str) or not re.match(r"^NCT[0-9]{8}$", nct):
            continue
        txt = _study_text(st)
        if not tokens:
            ok = True
        else:
            # require at least one token match (not overly strict)
            ok = any(t in txt for t in tokens)
        if ok:
            matched.append(st)

    # If nothing matched the expression, return empty results with succeeded status (reads matching nothing are not errors)
    # But this is a mutation, so we must still have an effect: the ct_search_requests row exists and will be succeeded with 0.
    # Also ensure we don't create ct_search_results rows if none.
    limited = matched[:max_studies]

    # ---- Create ct_search_results rows (idempotence: none for this new request yet) ----
    # rank starts at 1
    res_existing_ids = set()
    for r in search_results:
        if isinstance(r, dict) and isinstance(r.get("id"), str):
            res_existing_ids.add(r["id"])

    created_results = []
    for i, st in enumerate(limited, start=1):
        study_id = st.get("id")
        if not isinstance(study_id, str) or not study_id:
            continue
        # uniqueness constraints: (search_request_id, rank) and (search_request_id, study_id)
        # This is a new request id, so safe.
        res_id = _new_id("ctres", search_results)
        # keep from colliding with already generated by _new_id scanning full list
        if res_id in res_existing_ids:
            res_id = _new_id("ctres", search_results + [{"id": res_id}])
        row = {
            "id": res_id,
            "search_request_id": req_id,
            "study_id": study_id,
            "rank": i,
            "result_payload": {
                # lightweight summary from cached fields
                "nct_id": st.get("nct_id"),
                "brief_title": st.get("brief_title"),
                "overall_status": st.get("overall_status"),
                "conditions": st.get("conditions"),
                "study_type": st.get("study_type"),
            },
            "created_at": now,
            "updated_at": now,
        }
        search_results.append(row)
        created_results.append(row)

    if created_results:
        _save("ct_search_results.json", search_results)

    # ---- Optionally write CSV and create csv_exports record ----
    export_row = None
    if save_csv:
        # Determine columns: fields parameter or default
        default_cols = ["nct_id", "brief_title", "official_title", "overall_status", "study_type", "conditions"]
        cols = fields if fields is not None else default_cols

        # Create export record: pending -> writing -> completed/failed
        exp_id = _new_id("csvexp", exports)
        rel_dir = "exports"
        rel_path = os.path.join(rel_dir, f"{exp_id}_{filename}")
        export_row = {
            "id": exp_id,
            "search_request_id": req_id,
            "export_type": "fields_csv",
            "filename": filename,
            "relative_path": rel_path.replace("\\", "/"),
            "columns": cols,
            "row_count": None,
            "bytes": None,
            "file_sha256": None,
            "generated_at": None,
            "status": "pending",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        exports.append(export_row)
        _save("csv_exports.json", exports)

        # Transition pending -> writing
        export_row["status"] = "writing"
        export_row["updated_at"] = now
        _save("csv_exports.json", exports)

        abs_dir = os.path.join(_DB, rel_dir)
        abs_path = os.path.join(_DB, export_row["relative_path"])
        try:
            os.makedirs(abs_dir, exist_ok=True)
            # Write CSV
            with open(abs_path, "w", encoding="utf-8", newline="") as f:
                w = csv.writer(f)
                w.writerow(cols)
                for st in limited:
                    out = []
                    for c in cols:
                        v = st.get(c)
                        if isinstance(v, list):
                            out.append("; ".join([str(x) for x in v]))
                        elif isinstance(v, (dict,)):
                            out.append(json.dumps(v, ensure_ascii=False))
                        elif v is None:
                            out.append("")
                        else:
                            out.append(str(v))
                    w.writerow(out)

            # checksum + stat
            h = hashlib.sha256()
            with open(abs_path, "rb") as bf:
                for chunk in iter(lambda: bf.read(1024 * 1024), b""):
                    h.update(chunk)
            stinfo = os.stat(abs_path)

            export_row["status"] = "completed"
            export_row["row_count"] = len(limited)
            export_row["bytes"] = int(stinfo.st_size)
            export_row["file_sha256"] = h.hexdigest()
            export_row["generated_at"] = now
            export_row["updated_at"] = now
            export_row["error_message"] = None
            _save("csv_exports.json", exports)
        except Exception as e:
            # writing -> failed is allowed
            export_row["status"] = "failed"
            export_row["error_message"] = str(e)
            export_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            _save("csv_exports.json", exports)

    # ---- Finalize search request status ----
    req_row["results_count"] = len(limited)
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    req_row["status"] = "succeeded"
    req_row["error_message"] = None
    _save("ct_search_requests.json", reqs)

    latency_ms = int((time.time() - t0) * 1000)

    # Return results (empty allowed)
    return {
        "search_request": req_row,
        "results": created_results,
        "csv_export": export_row,
        "meta": {
            "max_studies": max_studies,
            "returned": len(created_results),
            "latency_ms": latency_ms,
        },
    }

def get_full_study_details(nct_id, **_extra):
    import json, os, datetime, time, re, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(nct_id, str) or not re.fullmatch(r"NCT\d{8}", nct_id.strip()):
        return _err("VALIDATION_ERROR", "nct_id must be a valid identifier like 'NCT01234567'")
    nct_id = nct_id.strip()

    studies = _load("ct_studies.json")

    def _new_id(prefix, existing_rows):
        existing = {r.get("id") for r in existing_rows if isinstance(r, dict)}
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        for i in range(1, 1000000):
            cid = f"{prefix}_{ts}_{i:06d}"
            if cid not in existing:
                return cid
        return f"{prefix}_{ts}_{int(time.time()*1000)}"

    def _fetch_full(nct):
        url = f"https://clinicaltrials.gov/api/v2/studies/{nct}"
        req = urllib.request.Request(url, headers={"Accept": "application/json", "User-Agent": "clinicaltrials-mcp-offline/1.0"})
        with urllib.request.urlopen(req, timeout=25) as resp:
            data = resp.read()
        return json.loads(data.decode("utf-8"))

    # Find existing
    row = None
    for st in studies:
        if isinstance(st, dict) and st.get("nct_id") == nct_id:
            row = st
            break

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # If already full, return cached payload
    if row and row.get("cache_status") == "full" and isinstance(row.get("full_payload"), dict):
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "nct_id": nct_id,
            "study": row,
            "payload": row.get("full_payload"),
            "meta": {"source": "cache", "latency_ms": latency_ms}
        }

    # Upsert row if missing
    if row is None:
        sid = _new_id("st", studies)
        row = {
            "id": sid,
            "nct_id": nct_id,
            "brief_title": None,
            "official_title": None,
            "overall_status": None,
            "conditions": None,
            "study_type": None,
            "start_date": None,
            "completion_date": None,
            "primary_location_countries": None,
            "source_last_updated_at": None,
            "full_payload": None,
            "payload_format": "ctgov_v2_json",
            "cache_status": "partial",
            "last_fetched_at": None,
            "fetch_error": None,
            "created_at": now,
            "updated_at": now,
        }
        studies.append(row)

    # Fetch upstream and update
    try:
        payload = _fetch_full(nct_id)
    except Exception as e:
        # Cache fetch failure
        # lifecycle: allow error from partial/full/stale
        row["cache_status"] = "error"
        row["fetch_error"] = f"{e}"
        row["last_fetched_at"] = now
        row["updated_at"] = now
        _save("ct_studies.json", studies)
        return _err("NOT_FOUND", "Study could not be retrieved from upstream", nct_id=nct_id, fetch_error=row["fetch_error"])

    if not isinstance(payload, dict) or not payload:
        row["cache_status"] = "error"
        row["fetch_error"] = "Upstream returned empty payload"
        row["last_fetched_at"] = now
        row["updated_at"] = now
        _save("ct_studies.json", studies)
        return _err("NOT_FOUND", "Study could not be retrieved from upstream", nct_id=nct_id)

    # Update cached fields (best effort)
    proto = payload.get("protocolSection") if isinstance(payload.get("protocolSection"), dict) else {}
    idmod = proto.get("identificationModule") if isinstance(proto.get("identificationModule"), dict) else {}
    statmod = proto.get("statusModule") if isinstance(proto.get("statusModule"), dict) else {}
    condmod = proto.get("conditionsModule") if isinstance(proto.get("conditionsModule"), dict) else {}
    designmod = proto.get("designModule") if isinstance(proto.get("designModule"), dict) else {}

    if isinstance(idmod.get("briefTitle"), str):
        row["brief_title"] = idmod.get("briefTitle")
    if isinstance(idmod.get("officialTitle"), str):
        row["official_title"] = idmod.get("officialTitle")
    if isinstance(statmod.get("overallStatus"), str):
        row["overall_status"] = statmod.get("overallStatus")
    if isinstance(condmod.get("conditions"), list):
        row["conditions"] = condmod.get("conditions")
    if isinstance(designmod.get("studyType"), str):
        row["study_type"] = designmod.get("studyType")

    row["full_payload"] = payload
    row["payload_format"] = "ctgov_v2_json"
    row["cache_status"] = "full"
    row["fetch_error"] = None
    row["last_fetched_at"] = now
    row["updated_at"] = now

    _save("ct_studies.json", studies)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "nct_id": nct_id,
        "study": row,
        "payload": payload,
        "meta": {"source": "upstream", "latency_ms": latency_ms}
    }

def get_study_statistics(condition=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if condition is not None:
        if not isinstance(condition, str):
            return _err("VALIDATION_ERROR", "condition must be a string when provided")
        if condition.strip() == "":
            return _err("VALIDATION_ERROR", "condition must not be an empty string when provided")
        condition = condition.strip()
        if len(condition) > 500:
            return _err("VALIDATION_ERROR", "condition is too long")

    # Create a ct_search_requests row for statistics
    reqs = _load("ct_search_requests.json")
    def _new_id(prefix, existing_rows):
        existing = {r.get("id") for r in existing_rows if isinstance(r, dict)}
        ts = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S")
        for i in range(1, 1000000):
            cid = f"{prefix}_{ts}_{i:06d}"
            if cid not in existing:
                return cid
        return f"{prefix}_{ts}_{int(time.time()*1000)}"

    search_request_id = _new_id("sr", reqs)
    sr = {
        "id": search_request_id,
        "search_type": "statistics",
        "search_expr": None,
        "keyword": None,
        "condition": condition,
        "max_studies": 1,
        "requested_fields": None,
        "save_csv": False,
        "filename": None,
        "results_count": None,
        "error_message": None,
        "status": "queued",
        "created_at": now,
        "updated_at": now,
    }
    reqs.append(sr)
    _save("ct_search_requests.json", reqs)

    # queued -> running
    sr["status"] = "running"
    sr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("ct_search_requests.json", reqs)

    studies = _load("ct_studies.json")
    results = _load("ct_search_results.json")

    # Decide dataset: prefer studies cache, but can use recent search_results for counts
    # We'll compute stats primarily from ct_studies, filtered by condition if provided.
    rows = [s for s in studies if isinstance(s, dict) and isinstance(s.get("nct_id"), str)]
    if not rows:
        sr["status"] = "failed"
        sr["error_message"] = "No cached studies available to compute statistics"
        sr["results_count"] = 0
        sr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("ct_search_requests.json", reqs)
        return _err("NOT_FOUND", "No cached data to compute statistics from")

    cond_l = condition.lower() if condition is not None else None
    def _matches_condition(st):
        if cond_l is None:
            return True
        conds = st.get("conditions")
        if isinstance(conds, list):
            for c in conds:
                if isinstance(c, str) and cond_l in c.lower():
                    return True
        # fallback: try to match in any recent result_payload conditions fields for this study
        sid = st.get("id")
        if sid:
            for rr in results[-5000:]:
                if rr.get("study_id") == sid and isinstance(rr.get("result_payload"), dict):
                    rp = rr["result_payload"]
                    # try common nesting
                    proto = rp.get("protocolSection") if isinstance(rp.get("protocolSection"), dict) else {}
                    condmod = proto.get("conditionsModule") if isinstance(proto.get("conditionsModule"), dict) else {}
                    rconds = condmod.get("conditions")
                    if isinstance(rconds, list):
                        for c in rconds:
                            if isinstance(c, str) and cond_l in c.lower():
                                return True
        return False

    filtered = [s for s in rows if _matches_condition(s)]
    if not filtered:
        sr["status"] = "failed"
        sr["error_message"] = "No cached studies matched the condition filter"
        sr["results_count"] = 0
        sr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("ct_search_requests.json", reqs)
        return _err("NOT_FOUND", "No cached data matched the condition filter")

    # Compute statistics
    by_status = {}
    by_type = {}
    cache_status = {}
    countries = {}

    for s in filtered:
        osr = s.get("overall_status")
        if isinstance(osr, str) and osr.strip():
            by_status[osr] = by_status.get(osr, 0) + 1
        stype = s.get("study_type")
        if isinstance(stype, str) and stype.strip():
            by_type[stype] = by_type.get(stype, 0) + 1
        cs = s.get("cache_status")
        if isinstance(cs, str):
            cache_status[cs] = cache_status.get(cs, 0) + 1
        pcs = s.get("primary_location_countries")
        if isinstance(pcs, list):
            for c in pcs:
                if isinstance(c, str) and c.strip():
                    countries[c] = countries.get(c, 0) + 1

    # finalize request
    sr["status"] = "succeeded"
    sr["results_count"] = len(filtered)
    sr["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("ct_search_requests.json", reqs)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "search_request": sr,
        "statistics": {
            "condition": condition,
            "study_count": len(filtered),
            "overall_status_counts": dict(sorted(by_status.items(), key=lambda kv: (-kv[1], kv[0]))),
            "study_type_counts": dict(sorted(by_type.items(), key=lambda kv: (-kv[1], kv[0]))),
            "cache_status_counts": dict(sorted(cache_status.items(), key=lambda kv: (-kv[1], kv[0]))),
            "top_countries": dict(sorted(countries.items(), key=lambda kv: (-kv[1], kv[0]))[:25]),
        },
        "meta": {"latency_ms": latency_ms}
    }

def load_csv_data(filename, **_extra):
    import json, os, datetime, time, hashlib, csv, io

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _iso_to_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_reqlog_id():
        # stable-enough unique id without external deps
        return "reqlog_" + now_dt.strftime("%Y%m%d%H%M%S") + "_" + str(int((time.time() % 1) * 1_000_000)).zfill(6)

    def _append_request_log(status, code=None, message=None, export_id=None):
        # Observable service dynamics: always attempt to record request
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_reqlog_id(),
            "endpoint": "load_csv_data",
            "status": status,
            "code": code,
            "message": message,
            "export_id": export_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        })
        _save("request_logs.json", logs)

    # ---- validate inputs ----
    if not isinstance(filename, str):
        try:
            _append_request_log("error", code="VALIDATION_ERROR", message="filename must be a string")
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "filename must be a string.")

    filename = filename.strip()
    if not filename:
        try:
            _append_request_log("error", code="VALIDATION_ERROR", message="filename must not be empty")
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "filename must not be empty.")
    if len(filename) > 255:
        try:
            _append_request_log("error", code="VALIDATION_ERROR", message="filename length must be between 1 and 255")
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "filename length must be between 1 and 255 characters.")
    # Reject path traversal and directory separators
    if ".." in filename or "/" in filename or "\\" in filename:
        try:
            _append_request_log("error", code="VALIDATION_ERROR", message="filename must be a base filename without path separators or '..'")
        except Exception:
            pass
        return _err(
            "VALIDATION_ERROR",
            "Invalid filename: path traversal is not allowed (business rule: reject any filename containing directory separators or '..')."
        )

    # ---- load exports and find best match ----
    exports = _load("csv_exports.json")
    if not isinstance(exports, list):
        exports = []

    candidates = []
    for r in exports:
        if not isinstance(r, dict):
            continue
        if r.get("filename") != filename:
            continue
        if r.get("status") != "completed":
            continue
        candidates.append(r)

    if not candidates:
        # If there are exports with same filename but not completed, give precise message
        any_same = [r for r in exports if isinstance(r, dict) and r.get("filename") == filename]
        if any_same:
            # Prefer to report most recent status for diagnostics
            def _sort_key(r):
                dt = _iso_to_dt(r.get("generated_at")) or _iso_to_dt(r.get("updated_at")) or _iso_to_dt(r.get("created_at")) or datetime.datetime.min
                return dt
            any_same.sort(key=_sort_key, reverse=True)
            st = any_same[0].get("status")
            msg = f"No completed CSV export found for that filename (most recent status is '{st}')."
        else:
            msg = "No CSV export record exists for that filename."
        try:
            _append_request_log("error", code="NOT_FOUND", message=msg)
        except Exception:
            pass
        return _err("NOT_FOUND", msg)

    # Prefer most recent generated_at, then updated_at/created_at
    def _cand_sort_key(r):
        return (
            _iso_to_dt(r.get("generated_at")) or datetime.datetime.min,
            _iso_to_dt(r.get("updated_at")) or datetime.datetime.min,
            _iso_to_dt(r.get("created_at")) or datetime.datetime.min,
        )

    candidates.sort(key=_cand_sort_key, reverse=True)
    chosen = candidates[0]
    export_id = chosen.get("id")
    rel = chosen.get("relative_path")

    # Validate relative_path exists and is safe-ish: must be a relative path (no absolute)
    if not isinstance(rel, str) or not rel.strip():
        try:
            _append_request_log("error", code="NOT_FOUND", message="Export record has no relative_path", export_id=export_id)
        except Exception:
            pass
        return _err("NOT_FOUND", "Export record is missing its relative_path; cannot locate CSV.")

    rel = rel.strip()
    if os.path.isabs(rel):
        # Treat as not found/invalid record rather than exposing path
        try:
            _append_request_log("error", code="NOT_FOUND", message="Export record has invalid absolute relative_path", export_id=export_id)
        except Exception:
            pass
        return _err("NOT_FOUND", "Export record has an invalid path; cannot locate CSV.")

    # Locate file. Prefer stored relative_path under a few plausible roots.
    # (Business rules only declare "relative path under the server's working/export directory".)
    candidate_paths = []
    # Common roots in similar servers; keep deterministic and safe.
    for root in ("/app/exports", "/app/export", "/app/workspace/exports", "/app/workdir/exports", "/app"):
        candidate_paths.append(os.path.normpath(os.path.join(root, rel)))

    file_path = None
    for p in candidate_paths:
        # ensure the join didn't escape root via rel like "../../"
        # Note: rel itself may contain subdirs; that's allowed by schema, but should not traverse upward.
        # We disallow any ".." path components in rel to prevent traversal.
        parts = [x for x in rel.replace("\\", "/").split("/") if x]
        if any(x == ".." for x in parts):
            try:
                _append_request_log("error", code="NOT_FOUND", message="Export record path contains traversal ('..')", export_id=export_id)
            except Exception:
                pass
            return _err("NOT_FOUND", "Export record has an unsafe path; cannot locate CSV.")
        if os.path.exists(p) and os.path.isfile(p):
            file_path = p
            break

    if file_path is None:
        # Must transition csv_exports.status to deleted or failed
        # Prefer 'deleted' per business rule, with timestamp update.
        updated = False
        for r in exports:
            if isinstance(r, dict) and r.get("id") == export_id:
                # lifecycle: completed -> deleted is allowed
                r["status"] = "deleted"
                r["updated_at"] = now
                updated = True
                break
        if updated:
            _save("csv_exports.json", exports)
        try:
            _append_request_log("error", code="NOT_FOUND", message="CSV file missing on disk; export soft-deleted", export_id=export_id)
        except Exception:
            pass
        return _err("NOT_FOUND", "CSV file is missing on disk for that completed export; export has been marked deleted.")

    # ---- read file contents ----
    try:
        with open(file_path, "rb") as f:
            data = f.read()
    except OSError:
        # file disappeared between exists() and open(); soft-delete
        updated = False
        for r in exports:
            if isinstance(r, dict) and r.get("id") == export_id:
                r["status"] = "deleted"
                r["updated_at"] = now
                updated = True
                break
        if updated:
            _save("csv_exports.json", exports)
        try:
            _append_request_log("error", code="NOT_FOUND", message="CSV file could not be opened; export soft-deleted", export_id=export_id)
        except Exception:
            pass
        return _err("NOT_FOUND", "CSV file could not be opened; export has been marked deleted.")

    # decode best-effort
    text = None
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        try:
            text = data.decode("utf-8-sig")
        except UnicodeDecodeError:
            # last resort
            text = data.decode("latin-1")

    # Optional: refresh stored bytes/sha256 if missing (do not change status)
    sha = hashlib.sha256(data).hexdigest()
    changed = False
    for r in exports:
        if isinstance(r, dict) and r.get("id") == export_id:
            if r.get("bytes") is None:
                r["bytes"] = len(data)
                changed = True
            if r.get("file_sha256") is None:
                r["file_sha256"] = sha
                changed = True
            if changed:
                r["updated_at"] = now
            break
    if changed:
        _save("csv_exports.json", exports)

    try:
        _append_request_log("ok", code=None, message="loaded", export_id=export_id)
    except Exception:
        pass

    return {
        "filename": filename,
        "export_id": export_id,
        "relative_path": rel,
        "bytes": len(data),
        "sha256": sha,
        "contents": text,
        "loaded_at": now,
    }

def list_saved_csv_files(status=None, export_type=None, search_request_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    allowed_status = {"pending", "writing", "completed", "failed", "deleted"}
    allowed_export_type = {"fields_csv", "full_studies_csv"}
    allowed_sort = {None, "generated_at", "-generated_at", "created_at", "-created_at", "filename", "-filename"}

    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter.")
    if export_type is not None and (not isinstance(export_type, str) or export_type not in allowed_export_type):
        return _err("VALIDATION_ERROR", "Invalid export_type filter.")
    if search_request_id is not None:
        if not isinstance(search_request_id, str) or not re.match(r"^ctsrch_[0-9A-HJKMNP-TV-Z]{26}$", search_request_id):
            return _err("VALIDATION_ERROR", "Invalid search_request_id filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort value.")

    exports = _load("csv_exports.json")

    # Enforce business rule: return only completed + file exists; if missing, soft-delete (completed->deleted) or failed
    changed = False
    filtered = []
    for e in exports:
        if not isinstance(e, dict):
            continue
        if e.get("status") == "completed":
            rel = e.get("relative_path")
            abs_path = os.path.join(_DB, rel) if isinstance(rel, str) else None
            if not abs_path or not os.path.isfile(abs_path):
                e["status"] = "deleted"
                e["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                e["error_message"] = None
                changed = True
                continue
            filtered.append(e)

    if changed:
        _save("csv_exports.json", exports)

    # Apply optional filters (note: these tools list "optionally filtered by status" but business rule overrides to completed+exists)
    if status is not None:
        filtered = [e for e in filtered if e.get("status") == status]
    if export_type is not None:
        filtered = [e for e in filtered if e.get("export_type") == export_type]
    if search_request_id is not None:
        filtered = [e for e in filtered if e.get("search_request_id") == search_request_id]

    # Sorting
    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    sort_key = sort or "-generated_at"
    reverse = sort_key.startswith("-")
    field = sort_key[1:] if reverse else sort_key

    def _k(e):
        v = e.get(field)
        if field in ("generated_at", "created_at"):
            dt = _parse_dt(v)
            return dt or datetime.datetime.min
        if isinstance(v, str):
            return v.lower()
        return ""

    filtered.sort(key=_k, reverse=reverse)

    # Cursor pagination (opaque base64 of index)
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("i:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start = int(raw[2:])
            if start < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(filtered)
    page = filtered[start:start + limit]
    next_i = start + limit
    has_more = next_i < total
    next_cursor = base64.urlsafe_b64encode(f"i:{next_i}".encode("utf-8")).decode("utf-8") if has_more else None

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_key,
        }
    }

def list_search_requests(status=None, search_type=None, created_after=None, created_before=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
