    if search_type is not None and (not isinstance(search_type, str) or search_type not in allowed_type):
        return _err("VALIDATION_ERROR", "Invalid search_type filter.")

    def _parse_rfc3339(s, fieldname):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return _err("VALIDATION_ERROR", f"{fieldname} must be an RFC3339 date-time string.")
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return _err("VALIDATION_ERROR", f"{fieldname} must be an RFC3339 date-time string.")

    ca = _parse_rfc3339(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_rfc3339(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "created_at:desc"
    if not isinstance(sort, str) or sort not in allowed_sort:
