        if search_type is not None and r.get("search_type") != search_type:
            continue
        cdt = _parse_dt(r.get("created_at"))
        if ca is not None and (cdt is None or cdt < ca):
            continue
        if cb is not None and (cdt is None or cdt > cb):
            continue
        filtered.append(r)

    # Sort
    field, direction = sort.split(":")
    reverse = direction == "desc"
    def _k(r):
        dt = _parse_dt(r.get(field))
        return dt or datetime.datetime.min
    filtered.sort(key=_k, reverse=reverse)

    # Cursor pagination: opaque base64 index
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("i:"):
