def get_search_request(id, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "succeeded"
    resp = None

    # Minimal observable dynamics: append to a request log if one exists.
    def _log_call(endpoint, request_meta, status, error=None):
        # Best-effort: if no log collection exists, do nothing.
        candidates = ["request_logs.json", "usage_logs.json", "audit_logs.json", "ct_request_logs.json", "ct_usage.json"]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "request": request_meta,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    try:
        if not isinstance(id, str) or not id.strip():
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "id must be a non-empty string.")
            return resp
        if len(id) > 2000:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "id is too long.")
            return resp

        reqs = _load("ct_search_requests.json")
        if not isinstance(reqs, list):
            reqs = []

        row = next((r for r in reqs if isinstance(r, dict) and r.get("id") == id), None)
        if row is None:
            status_code = "failed"
            resp = _err("NOT_FOUND", "Search request not found.", id=id)
            return resp

        resp = {"search_request": row}
        return resp
    except Exception as e:
        status_code = "failed"
        resp = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        return resp
    finally:
        _log_call("get_search_request", {"id": id}, status_code, resp.get("error") if isinstance(resp, dict) else None)

def get_search_results(search_request_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
