    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "succeeded"
    resp = None

    def _log_call(endpoint, request_meta, status, error=None):
        candidates = ["request_logs.json", "usage_logs.json", "audit_logs.json", "ct_request_logs.json", "ct_usage.json"]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "request": request_meta,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return None
        # Accept either plain integer rank offset, or base64 encoded JSON {"after_rank": int}
        if c.isdigit():
            return int(c)
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("after_rank"), int) and obj["after_rank"] >= 0:
                return obj["after_rank"]
        except Exception:
            return None
        return None

    def _encode_cursor(after_rank):
        payload = {"after_rank": after_rank}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    try:
        if not isinstance(search_request_id, str) or not search_request_id.strip():
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "search_request_id must be a non-empty string.")
            return resp

        if limit is None:
            limit = 100
        if not isinstance(limit, int):
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "limit must be an integer.")
            return resp
        if limit < 1 or limit > 500:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "limit must be between 1 and 500.")
            return resp

        after_rank = _decode_cursor(cursor)
        if after_rank is None:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "Invalid cursor.")
            return resp

        reqs = _load("ct_search_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        parent = next((r for r in reqs if isinstance(r, dict) and r.get("id") == search_request_id), None)
        if parent is None:
            status_code = "failed"
            resp = _err("NOT_FOUND", "Parent search request not found.", search_request_id=search_request_id)
            return resp

        results = _load("ct_search_results.json")
        if not isinstance(results, list):
            results = []

        # Enforce FK integrity: if any result rows reference missing parent, they should not be returned.
        filtered = []
        for r in results:
            if not isinstance(r, dict):
                continue
            if r.get("search_request_id") != search_request_id:
                continue
            rank = r.get("rank")
            if not isinstance(rank, int):
                continue
            if rank <= after_rank:
                continue
            filtered.append(r)

        filtered.sort(key=lambda x: x.get("rank", 0))

        page = filtered[:limit]
        has_more = len(filtered) > len(page)
        next_cursor = _encode_cursor(page[-1]["rank"]) if has_more and page else None

        resp = {
            "search_request_id": search_request_id,
            "results": page,
            "pagination": {
                "limit": limit,
                "total": len(filtered),
                "has_more": has_more,
                "next_cursor": next_cursor,
            },
        }
        return resp
    except Exception as e:
        status_code = "failed"
        resp = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        return resp
    finally:
        _log_call(
            "get_search_results",
            {"search_request_id": search_request_id, "limit": limit, "cursor": cursor},
            status_code,
            resp.get("error") if isinstance(resp, dict) else None,
        )

def list_cached_studies(cache_status=None, overall_status=None, condition=None, nct_id=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, uuid, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0403000" if __import__("os").path.isdir("./environment_mix/0403000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "succeeded"
    resp = None

    def _log_call(endpoint, request_meta, status, error=None):
        candidates = ["request_logs.json", "usage_logs.json", "audit_logs.json", "ct_request_logs.json", "ct_usage.json"]
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "id": "log_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "request": request_meta,
            "status": status,
            "error": error,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
        }
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                break

    def _decode_cursor(c):
        if c is None:
            return {"offset": 0}
        if not isinstance(c, str) or not c:
            return None
        if c.isdigit():
            return {"offset": int(c)}
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"=" * (-len(c) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return {"offset": obj["offset"]}
        except Exception:
            return None
        return None

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _dt_key(v):
        # Sort key that safely compares datetimes stored as ISO strings (or None)
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return str(v)
        if isinstance(v, str):
            return v
        return ""

    try:
        allowed_cache = {None, "partial", "full", "stale", "error"}
        if cache_status not in allowed_cache:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "Invalid cache_status.")
            return resp

        if overall_status is not None and (not isinstance(overall_status, str) or not overall_status.strip()):
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "overall_status must be a non-empty string when provided.")
            return resp

        if condition is not None and (not isinstance(condition, str) or not condition.strip()):
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "condition must be a non-empty string when provided.")
            return resp

        if nct_id is not None:
            if not isinstance(nct_id, str):
                status_code = "failed"
                resp = _err("VALIDATION_ERROR", "nct_id must be a string.")
                return resp
            if not re.fullmatch(r"NCT\d{8}", nct_id.strip()):
                status_code = "failed"
                resp = _err("VALIDATION_ERROR", "nct_id must match ^NCT[0-9]{8}$.")
                return resp
            nct_id = nct_id.strip()

        if limit is None:
            limit = 50
        if not isinstance(limit, int):
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "limit must be an integer.")
            return resp
        if limit < 1 or limit > 200:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
            return resp

        if sort is None:
            sort = "updated_at:desc"
        allowed_sort = {
            "created_at:desc", "created_at:asc",
            "updated_at:desc", "updated_at:asc",
            "last_fetched_at:desc", "last_fetched_at:asc",
        }
        if sort not in allowed_sort:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "Invalid sort.")
            return resp

        cur = _decode_cursor(cursor)
        if cur is None:
            status_code = "failed"
            resp = _err("VALIDATION_ERROR", "Invalid cursor.")
            return resp
        offset = cur["offset"]

        studies = _load("ct_studies.json")
        if not isinstance(studies, list):
            studies = []

        cond_lc = condition.lower() if isinstance(condition, str) else None

        def _matches(s):
            if not isinstance(s, dict):
                return False
            if cache_status is not None and s.get("cache_status") != cache_status:
                return False
            if overall_status is not None and s.get("overall_status") != overall_status:
                return False
            if nct_id is not None and s.get("nct_id") != nct_id:
                return False
            if cond_lc is not None:
                conds = s.get("conditions")
                if not isinstance(conds, list) or not conds:
                    return False
                ok = False
                for c in conds:
                    if isinstance(c, str) and cond_lc in c.lower():
                        ok = True
                        break
                if not ok:
                    return False
            return True

        filtered = [s for s in studies if _matches(s)]

        field, direction = sort.split(":")
        reverse = direction == "desc"
        filtered.sort(key=lambda r: _dt_key(r.get(field)), reverse=reverse)

        total = len(filtered)
        page = filtered[offset: offset + limit]
        has_more = (offset + limit) < total
        next_cursor = _encode_cursor(offset + len(page)) if has_more else None

        # Exclude full_payload from list responses
        sanitized = []
        for s in page:
            if not isinstance(s, dict):
                continue
            x = dict(s)
            if "full_payload" in x:
                x.pop("full_payload", None)
            sanitized.append(x)

        resp = {
            "studies": sanitized,
            "pagination": {
                "limit": limit,
                "total": total,
                "has_more": has_more,
                "next_cursor": next_cursor,
                "sort": sort,
            },
            "filters": {
                "cache_status": cache_status,
                "overall_status": overall_status,
                "condition": condition,
                "nct_id": nct_id,
            },
        }
        return resp
    except Exception as e:
        status_code = "failed"
        resp = _err("CONFLICT", "Unexpected server error.", detail=str(e))
        return resp
    finally:
        _log_call(
            "list_cached_studies",
            {"cache_status": cache_status, "overall_status": overall_status, "condition": condition, "nct_id": nct_id, "limit": limit, "cursor": cursor, "sort": sort},
            status_code,
            resp.get("error") if isinstance(resp, dict) else None,
        )
